SELECT ?z ?lbl ?light ?occ ?lightts ?occts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  ?z brick:hasPoint ?light .
  ?light a brick:ElectricPowerSensor .
  ?z brick:hasPoint ?occ .
  ?occ a brick:DiscreteStateSensor .
  OPTIONAL { ?light ref:hasTimeseriesId ?lightts }
  OPTIONAL { ?occ ref:hasTimeseriesId ?occts }
}

SELECT ?lbl ?point ?pc WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?lbl .
  ?z brick:hasPoint ?point .
  OPTIONAL { ?point a ?pc }
}

SELECT ?point ?pc ?ts WHERE {
  ?point a ?pc .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  FILTER (str(?point) CONTAINS "Zone_F4_Z05" && (str(?point) CONTAINS "Electric_Power" || str(?point) CONTAINS "Occupancy"))
}

